script.text:
			/* <flatten type="Javascript"> */
function load$Grid(g) {
	g._$k = [];
	g._$i = g._getColumnOrder('stt_rec');
	g._$t = g._getColumnOrder('tag');
	g.add_onResponseComplete(on$GridClosing$ResponseComplete);
	g.add_commandEvent(on$GridClosing$ExecuteCommand);
}
function scatter$Grid(g) {fill$Grid(g, true);}
function dispose$Grid(g) {
	try {g.remove_commandEvent(on$GridClosing$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridClosing$ResponseComplete);} catch (ex) {}
}
function on$GridClosing$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, id = g.get_id(), s = String.format('$find(\'{0}\')._focusWhenTabChanged();', id);
	switch (action) {
		case 'Create':
			if (isCheck$Grid(g)) request$Closing(id, action);
			break;
		case 'Truncate':
			if (isCheck$Grid(g)) {
				var e = (g._language == 'v' ? 'Hệ thống sẽ <span class="Highlight">xóa bút toán kết chuyển cho các bản ghi đang được chọn</span>, bạn có chắc chắn xóa không?' : 'The selected <span class="Highlight">closing transactions</span> will be deleted, are you sure you want to proceed?');
				$message.show(e, 0, String.format('request$Closing(\'{0}\', \'{1}\');', id, action), s);
			}
			break;
		case 'BeforeFormLoad':
			e.type.Value.set_vars([{Name: 'p1', Type: 'Decimal', Value: g._p1}, {Name: 'p2', Type: 'Decimal', Value: g._p2}, {Name: 'y', Type: 'Decimal', Value: g._y}, {Name: 'u', Type: 'String', Value: g._u}]);
			break;
		default:
			break;
	}
}
function request$Closing(id, c) {
	var g = $find(id);
	if (g._rowCount == 0) return;
	var r = (g._activeCell ? g._activeRow : 1), s = ',' + g._$k.join(',') + ',', o = g._getItemValue(r, g._$t);
	o.row = r;
	g.request(o, c, c, [['p1', 'Decimal', g._p1], ['p2', 'Decimal', g._p2], ['y', 'Decimal', g._y], ['u', 'String', g._u], ['s', 'Infinite', s]]);
}
function on$GridClosing$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object;
	switch (context) {
		case 'Create':
		case 'Truncate':
			var msg = (g._language == 'v' ? 'Chương trình đã thực hiện xong.' : 'The process completed successfully.');
			$message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
			g._$k = [];
			fill$Grid(g);

			for (var r = 1; r <= g._rowCount; r++) {
				g._setItemValue(r, g._getColumnOrder('ps_no'), 0);
			}

			if (context == 'Create') {
				for (var i = 0; i < result.length; i++) {
					for (var r = 1; r <= g._rowCount; r++) {
						if (g._getItemValue(r, g._getColumnOrder('stt_rec')) == result[i][1]) {
							g._setItemValue(r, g._getColumnOrder('ps_no'), result[i][2]);
							break;
						}
					}
				}
			}

			break;
		default:
			break;
	}
}
/* </flatten> */
			&ScriptTag;
